const OPENAI_API_KEY = 'PASTE_YOUR_KEY_HERE';
// ============================================

const items = $input.all();
const results = [];

for (const item of items) {
  const { id, source, message } = item.json;

  const prompt = `Analyze the following customer message and return a JSON object with these exact fields:

{
  "category": "<one of: Bug Report, Feature Request, Billing Issue, Technical Question, Incident/Outage>",
  "priority": "<one of: Low, Medium, High>",
  "confidence_score": <float between 0.0 and 1.0>,
  "core_issue": "<one sentence summarizing the core problem or request>",
  "extracted_entities": {
    "account_ids": ["<list of account IDs or URLs found>"],
    "invoice_numbers": ["<list of invoice numbers found>"],
    "error_codes": ["<list of error codes found>"],
    "monetary_amounts": ["<list of dollar amounts found>"],
    "systems_or_tools": ["<list of products, tools, or systems mentioned>"],
    "urgency_signal": "<none | low | medium | high>"
  },
  "summary": "<2-3 sentence human-readable summary for the receiving team>"
}

Rules:
- confidence_score should reflect how certain you are about the category assignment.
- urgency_signal should be "high" if the message mentions outages, downtime, or multiple users affected.
- Be precise with entity extraction. Only include entities actually present in the message.
- Return ONLY valid JSON. No markdown, no explanation.

Customer message (source: ${source}):
"""${message}"""`;

  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.openai.com/v1/chat/completions',
    headers: {
      'Authorization': `Bearer ${OPENAI_API_KEY}`,
      'Content-Type': 'application/json'
    },
    body: {
      model: 'gpt-4o-mini',
      temperature: 0.1,
      max_tokens: 600,
      messages: [
        { role: 'system', content: 'You are a precise JSON-outputting triage assistant for ArcVault, a B2B SaaS company. Return only valid JSON.' },
        { role: 'user', content: prompt }
      ]
    },
    json: true
  });

  let llmText = response.choices[0].message.content;
  llmText = llmText.replace(/```json\s*/g, '').replace(/```\s*/g, '').trim();
  const classification = JSON.parse(llmText);

  results.push({
    json: {
      request_id: id,
      source: source,
      raw_message: message,
      classification: classification
    }
  });
}

return results;

const items = $input.all();
const results = [];

for (const item of items) {
  const { request_id, source, raw_message, classification } = item.json;

  const routingMap = {
    'Bug Report': 'Engineering Queue',
    'Feature Request': 'Product Queue',
    'Billing Issue': 'Billing Queue',
    'Technical Question': 'IT/Security Queue',
    'Incident/Outage': 'Escalation Queue'
  };

  const category = classification.category;
  const confidence = parseFloat(classification.confidence_score) || 0;
  const messageLower = raw_message.toLowerCase();
  const destination = routingMap[category] || 'General Queue';

  const escalationReasons = [];

  // Rule 1: Low confidence
  if (confidence < 0.70) {
    escalationReasons.push('Low confidence score (' + confidence + ' < 0.70)');
  }

  // Rule 2: Incident/Outage always escalates
  if (category === 'Incident/Outage') {
    escalationReasons.push('Category is Incident/Outage');
  }

  // Rule 3: Escalation keywords
  const keywords = ['outage', 'down', 'stopped loading', 'unavailable', 'all users affected', 'multiple users affected'];
  for (const kw of keywords) {
    if (messageLower.includes(kw)) {
      escalationReasons.push("Message contains escalation keyword: '" + kw + "'");
      break;
    }
  }

  // Rule 4: Billing discrepancy > $500
  if (category === 'Billing Issue') {
    const amounts = classification.extracted_entities?.monetary_amounts || [];
    const values = amounts.map(a => parseFloat(String(a).replace(/[^\d.]/g, ''))).filter(v => !isNaN(v));
    if (values.length >= 2) {
      const discrepancy = Math.abs(values[0] - values[1]);
      if (discrepancy > 500) {
        escalationReasons.push('Billing discrepancy $' + discrepancy + ' exceeds $500 threshold');
      }
    }
  }

  const escalate = escalationReasons.length > 0;

  results.push({
    json: {
      request_id: request_id,
      source: source,
      raw_message: raw_message,
      timestamp: new Date().toISOString(),
      classification: {
        category: classification.category,
        priority: classification.priority,
        confidence_score: confidence
      },
      enrichment: {
        core_issue: classification.core_issue,
        extracted_entities: classification.extracted_entities
      },
      routing: {
        routed_to: escalate ? 'Escalation Queue' : destination,
        escalation_flag: escalate,
        escalation_reasons: escalationReasons
      },
      summary: classification.summary
    }
  });
}

return results;

